-- Run after migration in the same transaction and ROLLBACK.
do $$
declare u uuid; username text; product text; oldrow jsonb; legacy bigint; old_partial bigint; old_aql bigint; chem_code text; chem_id bigint; chem_time timestamptz; chem_data jsonb; chem_supplier text; nv text; nv_name text; nv_lot bigint;
 a jsonb; b jsonb; r jsonb; first_id bigint; lot bigint; token uuid:=gen_random_uuid(); stamp timestamptz; failed boolean;
 lot_data jsonb; first_round jsonb; second_round jsonb;
begin
 select user_id,user_roles.username into u,username from user_roles where role='admin' limit 1;
 select ma_sp into product from master_products order by ma_sp limit 1;
 if u is null or product is null then raise exception 'Missing staging fixture'; end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 select id,to_jsonb(l) into legacy,oldrow from iqc_lots l order by id limit 1;
 lot_data:=jsonb_build_object('received_at',now(),'supplier','BRV','product_code',product,'product_name','Fixture','lot_no','IQC-MULTIDAY-ROLLBACK','lot_qty',10000,'pham_vi','Đúc');
 first_round:=jsonb_build_object('ngay_kiem',current_date,'nguoi_kiem',username,'so_kiem',2000,'so_ok',1980,'so_ng',20,'loi','[{"ten_loi":"Xước","so_luong":20},{"ten_loi":"Ba via","so_luong":20}]'::jsonb);
 a:=iqc_luu_lan_kiem(null,lot_data,first_round,token);
 b:=iqc_luu_lan_kiem(null,lot_data,first_round,token);
 if a is distinct from b then raise exception 'Retry changed result'; end if;
 lot:=(a->>'lot_id')::bigint; first_id:=(a->>'lan_kiem_id')::bigint;
 if (select count(*) from iqc_lan_kiem where lot_id=lot)<>1 or (select count(*) from iqc_lan_kiem_loi where lan_kiem_id=first_id)<>2 then raise exception 'Create/retry mismatch'; end if;
 failed:=false;begin insert into iqc_lots(received_at,supplier,product_code,lot_no,lot_qty,pham_vi) values(now(),'BRV',product,'IQC-MULTIDAY-ROLLBACK',10000,'Đúc');exception when others then failed:=true;end;
 if not failed then raise exception 'Direct duplicate LOT accepted'; end if;
 second_round:=jsonb_build_object('ngay_kiem',current_date+1,'nguoi_kiem',username,'so_kiem',3000,'so_ok',2960,'so_ng',40,'loi','[]'::jsonb);
 b:=iqc_luu_lan_kiem(lot,null,second_round,gen_random_uuid());
 if (select sum(so_kiem) from iqc_lan_kiem where lot_id=lot)<>5000 then raise exception 'Incorrect aggregate'; end if;
 failed:=false; begin perform iqc_luu_lan_kiem(lot,null,second_round||'{"so_kiem":6000,"so_ok":5960}'::jsonb,gen_random_uuid()); exception when others then failed:=true; end;
 if not failed or (select count(*) from iqc_lan_kiem where lot_id=lot)<>2 then raise exception 'Excess allowed'; end if;
 failed:=false; begin perform iqc_luu_lan_kiem(null,lot_data||'{"lot_no":"IQC-MULTIDAY-BAD"}'::jsonb,first_round||'{"loi":[{"ten_loi":"","so_luong":0}]}'::jsonb,gen_random_uuid()); exception when others then failed:=true; end;
 if not failed or exists(select 1 from iqc_lots where lot_no='IQC-MULTIDAY-BAD') then raise exception 'Failed save left LOT'; end if;
 select sua_luc into stamp from iqc_lan_kiem where id=first_id;
 r:=iqc_sua_lan_kiem(first_id,first_round||'{"so_kiem":1000,"so_ok":990,"so_ng":10}'::jsonb,stamp,gen_random_uuid());
 if (select sum(so_kiem) from iqc_lan_kiem where lot_id=lot)<>4000 then raise exception 'Edit double counted'; end if;
 failed:=false; begin perform iqc_sua_lan_kiem(first_id,first_round,stamp,gen_random_uuid()); exception when others then failed:=true; end;
 if not failed then raise exception 'Stale edit accepted'; end if;
 failed:=false; begin update iqc_lots set ok_qty=999 where id=lot; exception when others then failed:=true; end;
 if not failed then raise exception 'Direct aggregate update allowed'; end if;
 select updated_at into stamp from iqc_lots where id=lot;
 r:=iqc_sua_thong_tin_lot(lot,jsonb_build_object('received_at',now(),'lot_qty',11000,'supplier','BRV','location','Kho','note','Kiểm thử'),stamp);
 if (r->>'lot_qty')::bigint<>11000 or not exists(select 1 from iqc_lich_su where loai='sua_thong_tin_lot' and khoa=lot::text) then raise exception 'LOT edit/audit failed'; end if;
 failed:=false; begin insert into iqc_defects(lot_id,defect_name,defect_qty) values(lot,'Bỏ qua lịch sử',1); exception when others then failed:=true; end;
 if not failed then raise exception 'Legacy defect insert allowed'; end if;
 perform iqc_tam_dung_lot(lot,true,'Test');
 failed:=false; begin perform iqc_luu_lan_kiem(lot,null,second_round,gen_random_uuid()); exception when others then failed:=true; end;
 if not failed then raise exception 'Paused LOT accepted new inspection'; end if;
 perform iqc_tam_dung_lot(lot,false,'');
 select updated_at into stamp from iqc_lots where id=lot;
 failed:=false;begin perform iqc_danh_gia_lot(lot,'OK',stamp);exception when others then failed:=true;end;
 if not failed then raise exception 'Incomplete LOT silently became OK'; end if;
 perform iqc_danh_gia_lot(lot,'NG',stamp);
 if (select iqc_ket_luan from iqc_lots where id=lot)<>'NG' then raise exception 'Explicit conclusion lost'; end if;
 perform iqc_luu_lan_kiem(lot,null,first_round||'{"so_kiem":1000,"so_ok":1000,"so_ng":0,"loi":[]}'::jsonb,gen_random_uuid());
 if (select iqc_ket_luan from iqc_lots where id=lot) is not null then raise exception 'Conclusion not invalidated after new inspection'; end if;
 a:=iqc_luu_lan_kiem(null,lot_data||'{"lot_no":"IQC-MULTIDAY-NEW"}'::jsonb,null,gen_random_uuid());
 if a->'lan_kiem_id'<>'null'::jsonb or exists(select 1 from iqc_lan_kiem where lot_id=(a->>'lot_id')::bigint) then raise exception 'Uninspected LOT incorrect'; end if;
 a:=iqc_luu_lan_kiem(null,lot_data||'{"lot_no":"IQC-MULTIDAY-FULL","lot_qty":100}'::jsonb,first_round||'{"so_kiem":100,"so_ok":100,"so_ng":0,"loi":[]}'::jsonb,gen_random_uuid());
 if (select status from iqc_lots where id=(a->>'lot_id')::bigint)<>'Đã kiểm tra' or coalesce((select result from iqc_lots where id=(a->>'lot_id')::bigint),'')<>'' then raise exception 'Full inspection automatically concluded OK'; end if;
 select updated_at into stamp from iqc_lots where id=(a->>'lot_id')::bigint;
 perform iqc_danh_gia_lot((a->>'lot_id')::bigint,'OK',stamp);
 if (select result from iqc_lots where id=(a->>'lot_id')::bigint)<>'OK' then raise exception 'Explicit OK not reflected'; end if;
 select sua_luc into stamp from iqc_lan_kiem where id=(a->>'lan_kiem_id')::bigint;
 perform iqc_sua_lan_kiem((a->>'lan_kiem_id')::bigint,first_round||'{"so_kiem":100,"so_ok":99,"so_ng":1,"loi":[]}'::jsonb,stamp,gen_random_uuid());
 if (select result from iqc_lots where id=(a->>'lot_id')::bigint)<>'NG' or (select iqc_ket_luan from iqc_lots where id=(a->>'lot_id')::bigint) is not null then raise exception 'Changed results retained OK'; end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 failed:=false; begin perform iqc_sua_lan_kiem(first_id,first_round,(select sua_luc from iqc_lan_kiem where id=first_id),gen_random_uuid()); exception when others then failed:=true; end;
 if not failed then raise exception 'Unauthorized edit accepted'; end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 insert into iqc_lots(received_at,supplier,product_code,product_name,lot_no,lot_qty,pham_vi,inspection_type,status,ok_qty,ng_qty,inspector)
 values(now(),'BRV',product,'Fixture','IQC-MULTIDAY-OLD',1599,'Đúc','Kiểm tra 100%','Đã kiểm tra',1500,0,username) returning id into old_partial;
 a:=iqc_luu_lan_kiem(old_partial,null,jsonb_build_object('ngay_kiem',current_date,'nguoi_kiem',username,'so_kiem',99,'so_ok',98,'so_ng',1,'loi','[]'::jsonb),gen_random_uuid());
 if (select sum(so_kiem) from iqc_lan_kiem where lot_id=old_partial)<>1599 or not exists(select 1 from iqc_lan_kiem where lot_id=old_partial and loai='so_du_cu' and ngay_kiem is null and so_ok=1500) or (select ok_qty from iqc_lots where id=old_partial)<>1598 then raise exception 'Legacy baseline incorrect'; end if;
 select sua_luc into stamp from iqc_lan_kiem where id=(a->>'lan_kiem_id')::bigint;
 perform iqc_sua_lan_kiem((a->>'lan_kiem_id')::bigint,jsonb_build_object('ngay_kiem',current_date,'nguoi_kiem',username,'so_kiem',99,'so_ok',99,'so_ng',0,'loi','[]'::jsonb),stamp,gen_random_uuid());
 if coalesce((select result from iqc_lots where id=old_partial),'')<>'' then raise exception 'Corrected new NG persisted as false legacy NG'; end if;
 failed:=false;begin select id,sua_luc into first_id,stamp from iqc_lan_kiem where lot_id=old_partial and loai='so_du_cu'; perform iqc_sua_lan_kiem(first_id,first_round,stamp,gen_random_uuid());exception when others then failed:=true;end;
 if not failed then raise exception 'Legacy baseline edit allowed'; end if;
 insert into iqc_lots(received_at,supplier,product_code,product_name,lot_no,lot_qty,pham_vi,inspection_type,status,sample_qty)
 values(now(),'BRV',product,'Fixture','IQC-MULTIDAY-AQL',10000,'Đúc','Kiểm tra AQL','Đã kiểm tra',800) returning id into old_aql;
 failed:=false;begin perform iqc_luu_lan_kiem(old_aql,null,first_round,gen_random_uuid());exception when others then failed:=true;end;
 if not failed or exists(select 1 from iqc_lan_kiem where lot_id=old_aql) then raise exception 'Unknown historical AQL inferred'; end if;
 select n.ma_nvl,n.nha_cung_cap into chem_code,chem_supplier from nvl_materials n join vat_lieu_mac m on m.ma_mac=n.ma_mac where n.nhom_vat_tu='kim_loai' and m.loai_kim_loai='nhom' limit 1;
 if chem_code is null then raise exception 'Missing chemical fixture'; end if;
 chem_data:=jsonb_build_object('request_id',gen_random_uuid(),'ma_nvl',chem_code,'ngay_kiem',current_date,'ca_kiem','Ca ngày','lot_no','CHEM-MULTIDAY-ROLLBACK','supplier',coalesce(chem_supplier,'BRV'),'inspector',username,'results','{}'::jsonb,'xac_nhan',false,'id_tieu_chuan',iqc_tc_hoa_hoc(chem_code,current_date)->'tieu_chuan'->'id');
 a:=iqc_luu_hoa_hoc(null,chem_data);chem_id:=(a->>'id')::bigint;
 select updated_at into chem_time from iqc_lots where id=chem_id;
 perform iqc_luu_hoa_hoc(chem_id,chem_data||jsonb_build_object('request_id',gen_random_uuid(),'updated_at',chem_time,'xac_nhan',true));
 if (select count(*) from iqc_phan_tich_hoa_hoc_lich_su where lot_id=chem_id)<>2 or exists(select 1 from iqc_lots where id=chem_id and (lot_qty<>0 or ok_qty<>0 or ng_qty<>0)) then raise exception 'Chemical history or PCS isolation failed'; end if;
 select ma_nvl,ten_nvl into nv,nv_name from nvl_materials where nhom_vat_tu<>'kim_loai' limit 1;
 if nv is null then raise exception 'Missing nonmetal fixture'; end if;
 a:=iqc_luu_lan_kiem(null,jsonb_build_object('received_at',now(),'supplier','BRV','product_code',nv,'product_name',nv_name,'lot_no','IQC-NVL-SNAPSHOT-ROLLBACK','lot_qty',10000,'pham_vi','Đúc','doi_tuong','nvl','ma_nvl',nv),first_round,gen_random_uuid());
 nv_lot:=(a->>'lot_id')::bigint;
 update nvl_materials set ten_nvl=ten_nvl||' test' where ma_nvl=nv;
 perform iqc_tam_dung_lot(nv_lot,true,'Test');
 if (select product_name from iqc_lots where id=nv_lot) is distinct from nv_name then raise exception 'Catalog rename changed historical NVL snapshot'; end if;
 if has_table_privilege('authenticated','iqc_lan_kiem','INSERT') or has_table_privilege('authenticated','iqc_lan_kiem_loi','UPDATE') or has_function_privilege('anon','iqc_luu_lan_kiem(bigint,jsonb,jsonb,uuid)','EXECUTE') then raise exception 'Direct or anonymous write granted'; end if;
 if legacy is not null and (select to_jsonb(l) from iqc_lots l where id=legacy) is distinct from oldrow then raise exception 'Legacy LOT changed'; end if;
 perform set_config('iqc.test.lot',lot::text,true);
end $$;
set local role authenticated;
do $$
declare failed boolean:=false; affected integer:=0; v_id bigint:=current_setting('iqc.test.lot')::bigint;
begin
 perform set_config('iqc.edit_lot',v_id::text,true);
 begin update iqc_lots set lot_qty=12000 where id=v_id;get diagnostics affected=row_count;exception when others then failed:=true;end;
 if not failed and affected<>0 then raise exception 'Authenticated user bypassed LOT guard with config'; end if;
end $$;
reset role;
